import numpy as np,pickle,json,base64,collections,re,cls,detail
K=detail.K
def D(*a): return dict(zip(K,a))
PK="Pleksus kardiakus (parasimpatis n. vagus X, simpatis T1–T4)."
DET={
'atrium_r':D("Ruang jantung penerima darah dari v. kava superior dan inferior serta sinus koronarius; memiliki aurikula, krista terminalis, dan fossa ovalis.","Menampung darah kurang oksigen dan mengalirkannya ke ventrikel kanan lewat katup trikuspid; nodus SA (pacu jantung) ada di dindingnya.",PK,"A. koroner kanan (cabang nodus SA dan atrial); darah vena lewat sinus koronarius.","V. kava superior dan inferior, ventrikel kanan, atrium kiri (septum interatrial), perikardium.","Fibrilasi atrium, defek septum atrium (foramen ovale paten), aritmia nodus SA, trombus atrium."),
'atrium_l':D("Ruang berdinding halus di bagian belakang jantung yang menerima empat vena pulmonalis; aurikula kiri berbentuk jari.","Menerima darah beroksigen dari paru dan mengalirkannya ke ventrikel kiri lewat katup mitral.",PK,"A. sirkumfleksa (cabang atrial kiri) dan a. koroner kanan; drainase ke sinus koronarius.","Vena pulmonalis, ventrikel kiri, esofagus (belakang), bronkus utama, aorta asendens.","Fibrilasi atrium (trombus aurikula kiri, risiko stroke), stenosis mitral, pembesaran menekan esofagus."),
'ventricle_r':D("Ruang berdinding tipis di bagian depan jantung dengan trabekula, otot papilaris, dan infundibulum menuju trunkus pulmonalis.","Memompa darah kurang oksigen ke paru lewat katup pulmonal (tekanan rendah).",PK+" Sistem konduksi: cabang berkas kanan.","A. koroner kanan (cabang marginal kanan dan interventrikular posterior), a. desendens anterior kiri.","Atrium kanan, ventrikel kiri (septum interventrikular), trunkus pulmonalis, sternum.","Gagal jantung kanan (kor pulmonale), infark ventrikel kanan, tetralogi Fallot, defek septum ventrikel."),
'ventricle_l':D("Ruang dengan dinding paling tebal (sekitar 10–15 mm) yang membentuk apeks jantung; trabekula halus dan dua otot papilaris.","Memompa darah beroksigen ke seluruh tubuh lewat katup aorta (tekanan tinggi).",PK+" Berkas His cabang kiri (fasikel anterior dan posterior).","A. koroner kiri (desendens anterior dan sirkumfleksa), a. koroner kanan (interventrikular posterior).","Atrium kiri, ventrikel kanan, aorta, perikardium, diafragma, paru kiri.","Infark miokard, kardiomiopati, hipertrofi ventrikel kiri, gagal jantung kiri, aneurisma ventrikel."),
'papillary':D("Tonjolan otot di dinding ventrikel yang melekat ke daun katup AV lewat korda tendinea.","Menahan daun katup agar tidak membalik ke atrium saat ventrikel berkontraksi.","Serat Purkinje dan pleksus kardiakus.","A. koroner (desendens anterior, sirkumfleksa, atau interventrikular posterior); otot posteromedial hanya satu sumber.","Korda tendinea, daun katup trikuspid atau mitral, dinding ventrikel.","Ruptur otot papilaris pasca infark (regurgitasi mitral akut), prolaps katup mitral."),
'tricuspid':D("Daun katup atrioventrikular kanan (anterior, posterior, septal) yang membentuk katup trikuspid.","Mencegah aliran balik dari ventrikel kanan ke atrium kanan.","Pleksus kardiakus.","Daun katup avaskular; cincin katup oleh a. koroner kanan.","Atrium kanan, ventrikel kanan, korda tendinea, otot papilaris.","Regurgitasi dan stenosis trikuspid, anomali Ebstein, endokarditis (pengguna narkoba suntik)."),
'mitral':D("Daun katup atrioventrikular kiri (anterior dan posterior) yang membentuk katup mitral (bikuspid).","Mencegah aliran balik dari ventrikel kiri ke atrium kiri.","Pleksus kardiakus.","Daun katup avaskular; cincin katup oleh a. sirkumfleksa.","Atrium kiri, ventrikel kiri, korda tendinea, otot papilaris, katup aorta.","Stenosis mitral (penyakit jantung rematik), regurgitasi mitral, prolaps katup mitral, endokarditis."),
'aortic_valve':D("Tiga daun semilunar (koroner kanan, koroner kiri, non-koroner) di pangkal aorta, dengan sinus Valsalva di belakangnya.","Mencegah aliran balik dari aorta ke ventrikel kiri saat diastol; a. koroner keluar dari sinus Valsalva.","Pleksus kardiakus.","Daun katup avaskular; a. koroner kanan dan kiri berasal dari sinus kanan dan kiri.","Ventrikel kiri (jalur keluar), aorta asendens, katup mitral, septum interventrikular.","Stenosis aorta (kalsifikasi, katup bikuspid), regurgitasi aorta, endokarditis, diseksi aorta."),
'pulm_valve':D("Tiga daun semilunar (anterior, kiri, kanan) di pangkal trunkus pulmonalis.","Mencegah aliran balik dari trunkus pulmonalis ke ventrikel kanan.","Pleksus kardiakus.","Daun katup avaskular; cincin katup oleh cabang a. koroner kanan dan desendens anterior.","Ventrikel kanan (infundibulum), trunkus pulmonalis, katup aorta.","Stenosis pulmonal kongenital, regurgitasi pulmonal, tetralogi Fallot."),
'rca':D("Keluar dari sinus aorta kanan, berjalan di sulkus atrioventrikular kanan ke bawah menuju krusis jantung.","Memasok atrium kanan, ventrikel kanan, nodus SA (sekitar 60%), nodus AV (sekitar 80%), dan septum bagian bawah.","Persarafan otonom pleksus kardiakus mengikuti arteri.","Cabang konus, nodus SA, marginal kanan, dan interventrikular posterior (dominansi kanan sekitar 70–80%).","Atrium kanan, aurikula kanan, ventrikel kanan, v. jantung kecil, sulkus koronarius.","Infark inferior (EKG II, III, aVF), blokade AV, infark ventrikel kanan, PCI dan CABG."),
'lca':D("Batang utama a. koroner kiri (left main) sekitar 1–2 cm dari sinus aorta kiri; bercabang menjadi LAD dan sirkumfleksa.","Memasok sebagian besar ventrikel kiri (sekitar 70% massa otot jantung).","Persarafan otonom pleksus kardiakus.","Cabang: a. desendens anterior kiri dan sirkumfleksa (kadang ramus intermedius).","Trunkus pulmonalis (depan), aurikula kiri (lateral), sinus aorta kiri.","Stenosis left main (infark luas berisiko tinggi), CABG."),
'lcx':D("Cabang kiri a. koroner kiri di sulkus atrioventrikular kiri, melingkari sisi kiri jantung.","Memasok atrium kiri serta dinding lateral dan posterior ventrikel kiri.","Persarafan otonom pleksus kardiakus.","Cabang marginal tumpul dan atrial kiri; nodus SA pada sekitar 40% orang.","Atrium kiri, sinus koronarius dan v. jantung besar, ventrikel kiri.","Infark lateral atau posterior (EKG I, aVL, V5–V6); dominansi kiri (sekitar 10%)."),
'lad':D("Cabang anterior a. koroner kiri di sulkus interventrikular anterior menuju apeks.","Memasok dinding anterior ventrikel kiri, apeks, dan dua pertiga anterior septum interventrikular.","Persarafan otonom pleksus kardiakus.","Cabang diagonal dan septal; beranastomosis dengan a. interventrikular posterior di apeks.","Ventrikel kanan dan kiri (sulkus), v. jantung besar, trunkus pulmonalis.","Infark anterior, angina, PCI, CABG (a. torakika interna ke LAD)."),
'cor_branch':D("Cabang arteri koroner: cabang inferolateral kanan (marginal kanan) dari a. koroner kanan dan cabang septal dari LAD.","Memasok dinding inferolateral ventrikel kanan dan septum interventrikular.","Persarafan otonom pleksus kardiakus.","Cabang a. koroner kanan dan LAD.","Ventrikel kanan, septum interventrikular, berkas His.","Infark septum (blokade berkas), infark ventrikel kanan, defek septum ventrikel pasca infark."),
'great_cardiac':D("Vena utama jantung yang naik di sulkus interventrikular anterior lalu melingkar di sulkus AV kiri menuju sinus koronarius.","Mengalirkan darah vena dari ventrikel dan atrium kiri serta septum anterior.","Pleksus kardiakus (vasomotor).","Bermuara ke sinus koronarius.","A. desendens anterior (berdampingan), a. sirkumfleksa, atrium dan ventrikel kiri.","Dipakai untuk elektroda terapi resinkronisasi jantung dan akses kateter."),
'coronary_sinus':D("Vena pendek dan lebar di belakang sulkus AV kiri yang bermuara ke atrium kanan.","Mengalirkan sekitar 60–70% darah vena jantung ke atrium kanan.","Pleksus kardiakus.","Menerima v. jantung besar, tengah, kecil, dan posterior.","Atrium kiri (belakang), atrium kanan (muara), a. sirkumfleksa.","Akses elektroda pacu, kardioplegia retrograd, pelebaran pada hipertensi atrium kanan."),
'middle_cardiac':D("Vena yang berjalan di sulkus interventrikular posterior menuju sinus koronarius.","Mengalirkan darah vena dari bagian belakang ventrikel dan septum.","Pleksus kardiakus.","Bermuara ke sinus koronarius.","A. interventrikular posterior, ventrikel kiri dan kanan, apeks.","Variasi anatomi penting pada pemasangan elektroda dan bedah jantung."),
'cor_vein':D("Vena kecil jantung yang bermuara ke sinus koronarius atau v. jantung besar, termasuk vena posterior dan inferior ventrikel kiri.","Mengalirkan darah vena dari dinding posterior dan inferior ventrikel kiri.","Pleksus kardiakus.","Bermuara ke sinus koronarius atau v. jantung besar.","Ventrikel kiri (permukaan diafragmatik), sinus koronarius.","Target elektroda CRT; variasi anatomi."),
'pulm_trunk':D("Pembuluh dari ventrikel kanan sepanjang sekitar 5 cm yang bercabang menjadi a. pulmonalis kanan dan kiri; ligamentum arteriosum menghubungkannya ke arkus aorta.","Membawa darah kurang oksigen ke paru.","Pleksus kardiakus; baroreseptor di bifurkasio.","Vasa vasorum dan cabang konus a. koroner.","Ventrikel kanan, aorta asendens, atrium kiri, arkus aorta (ligamentum arteriosum).","Emboli paru (sadel di bifurkasio), hipertensi pulmonal, duktus arteriosus paten, stenosis pulmonal."),
'pulm_artery':D("Dua cabang trunkus pulmonalis menuju hilus tiap paru; arteri kanan lebih panjang dan lewat di belakang aorta asendens.","Membawa darah kurang oksigen ke paru kanan dan kiri.","Pleksus pulmonalis (vagus dan simpatis).","Vasa vasorum dan cabang a. bronkialis.","Bronkus utama, vena pulmonalis, hilus paru.","Emboli paru, hipertensi pulmonal, malformasi arteriovenosa paru."),
'pulm_vein':D("Empat vena (dua tiap paru, superior dan inferior) yang bermuara ke atrium kiri.","Membawa darah kaya oksigen dari paru ke atrium kiri.","Pleksus pulmonalis.","Vasa vasorum dan a. bronkialis.","Atrium kiri, bronkus utama, a. pulmonalis (hilus).","Stenosis vena pulmonalis, fibrilasi atrium (fokus ektopik di muara vena pulmonalis, ablasi), anomali aliran vena pulmonalis."),
'aorta_asc':D("Bagian awal aorta sekitar 5 cm dari katup aorta sampai pangkal arkus; sinus Valsalva melahirkan a. koroner.","Mengalirkan darah beroksigen dari ventrikel kiri dan memasok jantung lewat a. koroner.","Pleksus kardiakus; baroreseptor dan kemoreseptor.","A. koroner kanan dan kiri; vasa vasorum.","Trunkus pulmonalis, atrium kanan, v. kava superior, perikardium.","Aneurisma aorta asendens, diseksi aorta tipe A (darurat), regurgitasi aorta, sindrom Marfan."),
'aortic_arch':D("Lengkungan aorta di mediastinum superior dengan tiga cabang: trunkus brakiosefalika, a. karotis komunis kiri, a. subklavia kiri.","Mengalirkan darah ke kepala, leher, lengan, dan aorta desendens; baroreseptor mengatur tekanan darah.","N. vagus kiri dan n. laringeus rekuren kiri (melingkari arkus), n. frenikus kiri; pleksus kardiakus.","Vasa vasorum; cabang bronkial dan perikardial kecil.","Trakea, esofagus, duktus torasikus, trunkus pulmonalis, ligamentum arteriosum.","Diseksi aorta, koarktasio aorta, aneurisma arkus, kompresi n. laringeus rekuren (suara serak)."),
'brachiocephalic':D("Cabang pertama arkus aorta yang pendek (sekitar 4–5 cm), bercabang menjadi a. karotis komunis kanan dan a. subklavia kanan.","Memasok darah beroksigen ke kepala, leher, dan lengan kanan.","Pleksus kardiakus dan serabut simpatis perivaskular.","Vasa vasorum.","Trakea (depan), v. brakiosefalika kiri (menyilang), pleura kanan.","Aneurisma, stenosis (sindrom subclavian steal), kompresi trakea, risiko fistula pada trakeostomi."),
'carotid':D("A. karotis komunis kanan dari trunkus brakiosefalika dan kiri langsung dari arkus aorta; naik di leher dalam selubung karotis.","Memasok darah ke kepala dan leher; bercabang menjadi a. karotis interna (otak) dan eksterna (wajah).","N. vagus (di selubung karotis), sinus karotikus oleh n. glosofaringeus (IX) dan vagus, simpatis.","Vasa vasorum.","V. jugularis interna, n. vagus, trakea, kelenjar tiroid, otot sternokleidomastoid.","Stenosis karotis (stroke iskemik), endarterektomi, diseksi karotis, sinkop sinus karotikus."),
'subclavian_a':D("Kanan dari trunkus brakiosefalika, kiri dari arkus aorta; lewat di antara skalenus anterior dan media menuju aksila.","Memasok lengan, leher bagian bawah (a. vertebralis, a. torakika interna), dan sebagian otak.","Pleksus brakialis (berjalan di sekitarnya); simpatis perivaskular.","Vasa vasorum; cabang: a. vertebralis, a. torakika interna, trunkus tirokervikalis.","Pleksus brakialis, v. subklavia, klavikula, rusuk 1, pleura apeks.","Sindrom subclavian steal, sindrom outlet toraks, cedera pada fraktur klavikula atau rusuk 1."),
'aorta_thoracic':D("Aorta desendens dari T4 sampai hiatus aorta diafragma di T12, melengkung di sisi kiri vertebra.","Memasok dinding toraks, paru (a. bronkialis), esofagus, dan perikardium.","Pleksus aorticus toraks (trunkus simpatikus dan vagus).","A. interkostalis posterior, a. bronkialis, a. esofageal.","Esofagus, duktus torasikus, v. azigos, vertebra torakal, paru kiri.","Diseksi aorta tipe B, aneurisma aorta torakal, koarktasio, trauma deselerasi."),
'aorta_abd':D("Lanjutan aorta di bawah diafragma (T12) sampai bifurkasio menjadi a. iliaka komunis di L4.","Memasok organ abdomen, dinding abdomen, pelvis, dan tungkai lewat cabang-cabangnya.","Pleksus aorticus abdominal (simpatis, ganglion seliakus dan mesenterika).","Cabang: a. seliaka, a. mesenterika superior dan inferior, aa. renalis, aa. lumbalis, a. iliaka komunis.","V. kava inferior (kanan), vertebra lumbal, duodenum, pankreas, ginjal.","Aneurisma aorta abdominal (risiko ruptur), aterosklerosis, sindrom Leriche, diseksi."),
'v_brachioceph':D("V. brakiosefalika kanan dan kiri terbentuk dari v. jugularis interna dan v. subklavia; keduanya bersatu membentuk v. kava superior.","Mengalirkan darah vena dari kepala, leher, dan lengan ke v. kava superior.","Pleksus kardiakus; n. frenikus dan vagus berdekatan.","Vasa vasorum; v. tiroidea inferior dan v. torakika interna bermuara.","Trunkus brakiosefalika, arkus aorta, timus, trakea.","Trombosis, sindrom v. kava superior, komplikasi kateter vena sentral."),
'v_subclavian':D("Lanjutan v. aksilaris di bawah klavikula yang bersatu dengan v. jugularis interna membentuk v. brakiosefalika.","Mengalirkan darah vena dari lengan.","Pleksus brakialis (berdekatan); simpatis.","Vasa vasorum.","A. subklavia, klavikula, rusuk 1, skalenus anterior, pleura apeks.","Trombosis (Paget-Schroetter), akses kateter vena sentral, pneumotoraks iatrogenik."),
'ivc':D("Vena terbesar tubuh, terbentuk dari v. iliaka komunis di L5; naik di sisi kanan aorta melewati hiatus v. kava diafragma (T8) menuju atrium kanan.","Mengalirkan darah vena dari tubuh bagian bawah (abdomen, pelvis, tungkai) ke atrium kanan.","Pleksus aorticus abdominal; n. frenikus di diafragma.","Vasa vasorum; menerima vv. lumbalis, renalis, hepatika, gonadal kanan.","Aorta abdominal, hati (alur v. kava), ginjal, duodenum, diafragma.","Trombosis vena dalam yang menyebar (filter IVC), kompresi saat kehamilan, tumor ginjal menginvasi v. kava.")}
GN=['Ruang Jantung','Katup Jantung','Pembuluh Koroner','Sirkulasi Paru','Aorta & Cabang Besar','Vena Besar']
def info(b):
    L=b.lower()
    ch={'Right_atrium':('Atrium Kanan','Atrium dextrum','atrium_r',0),'Left_atrium':('Atrium Kiri','Atrium sinistrum','atrium_l',0),'Right_ventricle':('Ventrikel Kanan','Ventriculus dexter','ventricle_r',0),'Left_ventricle':('Ventrikel Kiri','Ventriculus sinister','ventricle_l',0)}
    if b in ch: return ch[b]+(0,)
    if 'papillary' in L:
        w=re.match(r'^(\w+)_papillary_muscle_of_(right|left)_ventricle',b); a={'Inferior':'Inferior','Anterior':'Anterior','Septal':'Septal'}[w[1]]
        return ('Otot Papilaris %s Ventrikel %s'%(a,'Kanan' if w[2]=='right' else 'Kiri'),'Musculus papillaris %s ventriculi %s'%(w[1].lower(),'dextri' if w[2]=='right' else 'sinistri'),'papillary',0,1)
    if 'leaflet' in L:
        if 'right_atrioventricular' in L:
            w=b.split('_')[0]; return ('Daun Katup Trikuspid %s'%{'Inferior':'Inferior','Septal':'Septal','Anterior':'Anterior','Posterior':'Posterior'}[w],'Cuspis %s valvae atrioventricularis dextrae'%w.lower(),'tricuspid',1,1)
        if 'left_atrioventricular' in L:
            w=b.split('_')[0]; return ('Daun Katup Mitral %s'%w,'Cuspis %s valvae atrioventricularis sinistrae'%w.lower(),'mitral',1,1)
        if 'pulmonary_valve' in L:
            w=b.split('_')[0]; return ('Daun Katup Pulmonal %s'%{'Anterior':'Anterior','Left':'Kiri','Right':'Kanan'}[w],'Valvula semilunaris %s valvae trunci pulmonalis'%{'Anterior':'anterior','Left':'sinistra','Right':'dextra'}[w],'pulm_valve',1,1)
        n={'Left_coronary_leaflet':('Daun Katup Aorta Koroner Kiri','Valvula semilunaris sinistra valvae aortae'),'Right_coronary_leaflet':('Daun Katup Aorta Koroner Kanan','Valvula semilunaris dextra valvae aortae'),'Non-coronary_leaflet':('Daun Katup Aorta Non-koroner','Valvula semilunaris posterior valvae aortae')}[b]
        return n+('aortic_valve',1,1)
    m={'Right_coronary_artery':('Arteri Koroner Kanan','Arteria coronaria dextra','rca',2),'Left_coronary_artery':('Arteri Koroner Kiri (Left Main)','Arteria coronaria sinistra','lca',2),'Circumflex_artery_of_heart':('Arteri Sirkumfleksa','Ramus circumflexus arteriae coronariae sinistrae','lcx',2),'Anterior_interventricular_artery':('Arteri Desendens Anterior Kiri (LAD)','Ramus interventricularis anterior','lad',2),'Right_inferolateral_branch_of_right_coronary_artery':('Cabang Inferolateral Kanan Arteri Koroner Kanan','Ramus marginalis dexter','cor_branch',2),'Septal_branches_of_anterior_interventricular_artery':('Cabang Septal Arteri Desendens Anterior','Rami interventriculares septales','cor_branch',2),'Great_cardiac_vein':('Vena Jantung Besar','Vena cardiaca magna','great_cardiac',2),'Coronary_sinus':('Sinus Koronarius','Sinus coronarius','coronary_sinus',2),'Middle_cardiac_vein':('Vena Jantung Tengah','Vena cardiaca media','middle_cardiac',2),
     'Pulmonary_trunk':('Trunkus Pulmonalis','Truncus pulmonalis','pulm_trunk',3),'Bifurcation_of_pulmonary_trunk':('Percabangan Trunkus Pulmonalis','Bifurcatio trunci pulmonalis','pulm_trunk',3),'Right_pulmonary_artery':('Arteri Pulmonalis Kanan','Arteria pulmonalis dextra','pulm_artery',3),'Left_pulmonary_artery':('Arteri Pulmonalis Kiri','Arteria pulmonalis sinistra','pulm_artery',3),'Right_superior_pulmonary_vein':('Vena Pulmonalis Superior Kanan','Vena pulmonalis superior dextra','pulm_vein',3),'Right_inferior_pulmonary_vein':('Vena Pulmonalis Inferior Kanan','Vena pulmonalis inferior dextra','pulm_vein',3),'Left_superior_pulmonary_vein':('Vena Pulmonalis Superior Kiri','Vena pulmonalis superior sinistra','pulm_vein',3),'Left_inferior_pulmonary_vein':('Vena Pulmonalis Inferior Kiri','Vena pulmonalis inferior sinistra','pulm_vein',3),
     'Ascending_aorta':('Aorta Asendens','Aorta ascendens','aorta_asc',4),'Aortic_arch':('Arkus Aorta','Arcus aortae','aortic_arch',4),'Brachiocephalic_trunk':('Trunkus Brakiosefalika','Truncus brachiocephalicus','brachiocephalic',4),'Right_common_carotid_artery':('Arteri Karotis Komunis Kanan','Arteria carotis communis dextra','carotid',4),'Left_common_carotid_artery':('Arteri Karotis Komunis Kiri','Arteria carotis communis sinistra','carotid',4),'Right_subclavian_artery':('Arteri Subklavia Kanan','Arteria subclavia dextra','subclavian_a',4),'Left_subclavian_artery':('Arteri Subklavia Kiri','Arteria subclavia sinistra','subclavian_a',4),'Thoracic_aorta':('Aorta Torakalis','Aorta thoracica','aorta_thoracic',4),'Abdominal_aorta':('Aorta Abdominalis','Aorta abdominalis','aorta_abd',4),
     'Right_brachiocephalic_vein':('Vena Brakiosefalika Kanan','Vena brachiocephalica dextra','v_brachioceph',5),'Left_brachiocephalic_vein':('Vena Brakiosefalika Kiri','Vena brachiocephalica sinistra','v_brachioceph',5),'Right_subclavian_vein':('Vena Subklavia Kanan','Vena subclavia dextra','v_subclavian',5),'Left_subclavian_vein':('Vena Subklavia Kiri','Vena subclavia sinistra','v_subclavian',5),'Inferior_vena_cava_(thoracic_part)':('Vena Kava Inferior (Bagian Toraks)','Vena cava inferior pars thoracica','ivc',5),'Inferior_vena_cava_(abdominal_part)':('Vena Kava Inferior (Bagian Abdomen)','Vena cava inferior pars abdominalis','ivc',5)}
    if b in m: return m[b]+(0,)
    if b.startswith('Inferior_vein_of_left_ventricle'):
        return (('Vena Posterior Ventrikel Kiri','Vena posterior ventriculi sinistri') if '(' in b else ('Vena Inferior Ventrikel Kiri','Vena inferior ventriculi sinistri'))+('cor_vein',2,1)
    raise KeyError(b)
org=pickle.load(open('hrt.pkl','rb')); seen=set(); ms=[]
for i,V,F in org:
    k=(V.shape,round(float(V.sum()),3))
    if k in seen: continue
    seen.add(k); used=np.unique(F); r=-np.ones(len(V),int); r[used]=np.arange(len(used)); ms.append((cls.names[i],V[used].astype(np.float64),r[F]))
A=np.vstack([m[1] for m in ms]); mn=A.min(0); sc=float((A.max(0)-mn).max())
vb=bytearray(); fb=bytearray(); meta=[]
for n,V,F in ms:
    assert len(V)<65536
    q=np.round((V-mn)/sc*65535).astype(np.uint16); meta.append([n,len(V),len(F),len(vb)//2,len(fb)//2]); vb+=q.tobytes(); fb+=F.astype(np.uint16).tobytes()
nv=len(vb)//2
for m in meta: m[4]+=nv
blob=bytes(vb)+bytes(fb); M={'mn':mn.tolist(),'sc':sc,'meta':meta}
its=collections.OrderedDict()
for i,m in enumerate(meta):
    b,s,side,t=cls.split(m[0]); it=its.setdefault(b,{'p':[],'s':set()}); it['p'].append(i)
sdf=lambda b:'garis tengah' if re.search('leaflet|bifurcation|trunk|arch|aorta|sinus|coronary_artery',b,re.I) and not re.match('(Right|Left)_(coronary_artery|common|subclavian|pulmonary)',b) else 'kanan' if b.startswith('Right') or '_right_' in b else 'kiri' if b.startswith('Left') or '_left_' in b else 'garis tengah'
G=[[] for _ in GN]
for b,it in its.items():
    r=info(b); n,l,d,g=r[:4]; gen=r[4] if len(r)>4 else 0
    o={'id':b,'n':n,'l':l,'e':b.replace('_',' '),'r':GN[g],'s':sdf(b),'p':it['p'],'d':d}
    if gen: o['g']=1
    assert d in DET,d
    G[g].append((n,o))
groups=[{'g':GN[i],'items':[o for _,o in sorted(G[i],key=lambda x:x[0])]} for i in range(6)]
print([(g['g'],len(g['items'])) for g in groups],len(meta),sum(m[2] for m in meta),len(blob)/1e6)
json.dump({'g':groups,'DET':DET},open('hrt_meta.json','w'),ensure_ascii=False)
open('/mnt/user-data/outputs/data/atlas_jantung.json','w').write(json.dumps({'b':base64.b64encode(blob).decode(),'m':M},separators=(',',':')))
